# Review TLS and wireless settings against a minimum standard.
WEAK_PROTOCOLS = {'SSLv3', 'TLSv1.0', 'TLSv1.1'}
WEAK_CIPHER_WORDS = ('RC4', '3DES', 'NULL', 'EXPORT', 'MD5')
WEAK_WIFI = {'WEP', 'WPA', 'WPA2-TKIP'}

services = [
    ('student portal', ['TLSv1.2', 'TLSv1.3'], ['TLS_AES_128_GCM_SHA256', 'ECDHE-RSA-AES128-GCM-SHA256'], True),
    ('old admin panel', ['TLSv1.0', 'TLSv1.2'], ['ECDHE-RSA-AES128-GCM-SHA256', 'DES-CBC3-SHA'], False),
]
for name, protocols, ciphers, hsts in services:
    issues = [f'disable {p}' for p in protocols if p in WEAK_PROTOCOLS]
    issues += [f'remove {c}' for c in ciphers if any(w in c.upper() or (w == '3DES' and 'DES-CBC3' in c.upper()) for w in WEAK_CIPHER_WORDS)]
    if not hsts:
        issues.append('enable HSTS')
    print(f"{name:<16} {'; '.join(issues) if issues else 'meets standard'}")

for ssid, security in [('Institute-Staff', 'WPA3-Enterprise'), ('Institute-Guest', 'WPA2-TKIP')]:
    print(f"Wi-Fi {ssid:<16} {'upgrade to WPA3 (or WPA2-AES at minimum)' if security in WEAK_WIFI else 'meets standard'}")
